VALUES ('ee1e8e56-acdsdssd-b370-b38d2dbdc3e0', 'test_project_id', 'ddddd11', 'ddd树大招风1111', 'data:image/svg+xml;base64,', NULL, 'b5eab28e-cab2-4e76-acf2-2f53a09aa59d', 'AgentBuilder-V3134-38B-Base-4K', '{"top_p":1.0,"temperature":0.0,"history_size":20,"output_format":"text","max_tokens":2048,"frequency_penalty":0.0,"enable_thinking":true}', '# Role: \n\n## Profile:\n- author: Arthur\n- version: 0.1\n- language: 中文\n- description: 一个高效可靠的周报生成器，能够将用户输入的信息转化为一份高质量的周报\n\n## Goals:\n- 接收用户输入的周报信息\n- 对周报信息进行筛选和精简\n- 将周报信息按照结构化格式排版\n- 将排版好的周报输出\n- 周报的阅读对象是直d属领导, 请注意周报的措词和语气\n\n## Constrains:\n- 适当扩写用户提供的信息\n- 不向用户主动索取其他信息\n- 按照用户提供的截止日期完成工作\n\n## Skills:\n- 精准地理解用户的需求\n- 熟练掌握文字排版的规则及技巧\n- 使用 UNICODE 字符对排版进行美化\n- 获取系统时间并按照指定格式进行输出\n- 写作与编辑能力\n\n## Workflows:\n1. 用户提交相关信息后，将信息进行结构化分类，并按照提供的格式进行排版\n2. 输出已完成的周报，并将周报发送给用户进行确认. 如果用户批准，周报就完成了；如果用户不满意，我们将对其进行修改和完善直到得到用户的满意为止。\n{{aa}}', NULL, '[]', '', '[]', '{"enable":true,"rounds":1,"prompt":"- 问题应该与你最后一轮的回复紧密相关\n- 问题不要与上文已经提问或者回答过的内容重复\n- 每句话只包含一个问题，但也可以不是问句而是一句指令\n- 推荐你有能力回答的问题"}', '{"domain":"common","language":"chinese","timbre":"huaxiaohe"}', '', 'agent/ir/ee1e8e56-acd1-420e-b370-b38d2dbdc3e0/ee1e8e56-acd1-420e-b370-b38d2dbdc3e0.json', 'agent', 'planexecute', 'published', 'agent_builder', '6f80301edacc43728bf47b6a6484d512', '2026-02-11 10:34:31', '2026-02-23 10:56:41', '2026-02-23 10:39:32', 'LLM', NULL, 0, 'PlanExecute', NULL, '{"enabled":true,"filter":{"keywords":""},"replace":[],"reply":[]}', 'default', 'ee1e8e56-acd1-420e-b370-b38d2dbdc3e0', NULL, '0c72472bfe4647168124456891091495', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL);
